import numpy as np
import pandas as pd
arr = np.array([0], dtype='i4')
constructors = {
    'Index': lambda: pd.Index(arr),
    'MultiIndex(levels/codes)': lambda: pd.MultiIndex(levels=[arr], codes=[[0]], names=['a']),
    'from_arrays': lambda: pd.MultiIndex.from_arrays([arr], names=['a']),
    'from_tuples': lambda: pd.MultiIndex.from_tuples(list(zip(arr)), names=['a']),
}
for name, fn in constructors.items():
    obj = fn()
    if isinstance(obj, pd.MultiIndex):
        print(name, obj.levels[0].dtype, obj.get_level_values(0).dtype)
    else:
        print(name, obj.dtype)
